-- 外研社七下 wy7B 听力灌库(junior_listening_exercises)· publisher=junior_fltrp · volume=wy7B · grade=7 · 6单元×6=36
-- 3对话+2独白+1通知/单元 · 每篇2题4选1 · UK英音单音色(speaker=fable) · audio_url先NULL(跑pregenerate --volume=wy7B后回填)
-- ★DELETE 带 publisher='junior_fltrp' AND volume='wy7B' 双限★
BEGIN;
DELETE FROM public.junior_listening_exercises WHERE publisher='junior_fltrp' AND volume='wy7B';
INSERT INTO public.junior_listening_exercises
  (id, grade, publisher, volume, unit, title, topic, transcript, translation_cn, audio_url, speaker, kind, duration_sec, difficulty, questions, key_vocab) VALUES
  ('556858b6-4bde-ae38-93c1-d4d7843a21b0', 7, 'junior_fltrp', 'wy7B', 'U1', 'A happy day', '回忆开心的一天(过去时)', 'A: You look so happy today, Ben. What happened?
B: I had a wonderful day yesterday. My family went to the countryside.
A: That sounds nice! What did you do there?
B: We climbed a small hill and had a picnic. I saw many beautiful birds.
A: Lucky you! Did you take any photos?
B: Yes, lots of them. It was such a happy day.', 'A:Ben你今天真开心,怎么了?B:我昨天过了美好的一天,全家去了乡下。A:真好!你们在那做了什么?B:我们爬了座小山、野餐,我看到好多漂亮的鸟。A:真幸运!拍照了吗?B:拍了好多,那是我这周最开心的一天。', NULL, 'fable', 'dialogue', 32, 1, '[{"type": "choice", "q": "What did Ben''s family do yesterday?", "options": ["Stayed at home.", "Visited a museum.", "Went to the countryside.", "Watched a film."], "answer": "C", "explanation": "''My family went to the countryside.''"}, {"type": "choice", "q": "How did Ben feel about the day?", "options": ["It was boring.", "It was tiring.", "It was too long.", "It was a very happy day."], "answer": "D", "explanation": "''It was such a happy day.''"}]'::jsonb, '[{"word": "picnic", "cn": "野餐"}, {"word": "countryside", "cn": "乡下"}]'::jsonb),
  ('002f86ec-8146-3a7d-fd36-a6eb50ea39e8', 7, 'junior_fltrp', 'wy7B', 'U1', 'My birthday present', '收到的礼物(过去时)', 'A: Hi Lily, how was your birthday?
B: It was great! My parents gave me a new bike.
A: Wow, a bike! Did you ride it?
B: Yes, I rode it in the park with my friends. We had so much fun.
A: That''s wonderful. Happy birthday again!
B: Thank you! It was a birthday I will never forget.', 'A:嗨Lily,生日过得怎么样?B:很棒!爸妈送了我一辆新自行车。A:哇自行车!骑了吗?B:骑了,和朋友在公园里骑,玩得可开心了。A:太好了,再次生日快乐!B:谢谢!这是个我永远不会忘的生日。', NULL, 'fable', 'dialogue', 29, 1, '[{"type": "choice", "q": "What did Lily''s parents give her?", "options": ["A book.", "A new bike.", "A phone.", "A cake."], "answer": "B", "explanation": "''My parents gave me a new bike.''"}, {"type": "choice", "q": "Why will Lily never forget this birthday?", "options": ["It was happy and full of fun.", "It was very quiet.", "She was ill that day.", "She got no presents."], "answer": "A", "explanation": "骑车、和朋友玩得开心 → 难忘。"}]'::jsonb, '[{"word": "present", "cn": "礼物"}, {"word": "forget", "cn": "忘记"}]'::jsonb),
  ('4401932c-90ad-1984-47dd-3e7d50b50f26', 7, 'junior_fltrp', 'wy7B', 'U1', 'The lost dog', '帮助找狗(过去时·助人幸福)', 'A: Why are you so happy, Kate?
B: This morning I found a lost dog near my home.
A: Oh no, was it afraid?
B: A little. I gave it some water and looked at its name card.
A: Did you find its owner?
B: Yes! An old man came and thanked me. His smile made me really happy.', 'A:Kate你怎么这么开心?B:今早我在家附近发现一只走失的狗。A:哦不,它害怕吗?B:有点。我给它喝了水,看了它的名牌。A:找到主人了吗?B:找到了!一位老人来了、谢了我。他的笑容让我特别开心。', NULL, 'fable', 'dialogue', 29, 2, '[{"type": "choice", "q": "What did Kate find this morning?", "options": ["A name card.", "An old man.", "A lost dog.", "A bottle of water."], "answer": "C", "explanation": "''I found a lost dog near my home.''"}, {"type": "choice", "q": "What made Kate happy?", "options": ["Getting a present.", "Helping the dog find its owner.", "Winning a game.", "Buying a dog."], "answer": "B", "explanation": "帮狗找到主人、老人道谢 → 助人为乐。"}]'::jsonb, '[{"word": "owner", "cn": "主人"}, {"word": "afraid", "cn": "害怕的"}]'::jsonb),
  ('c8f9597d-b5f7-3dd6-7cbd-13cc50b3d041', 7, 'junior_fltrp', 'wy7B', 'U1', 'My grandma''s garden', '独白·童年幸福回忆(过去时)', 'When I was young, I often stayed at my grandma''s house in summer. She had a small garden behind the house. Every morning, we watered the flowers together. In the afternoon, grandma told me old stories under the big tree. Sometimes we picked fresh fruit and made sweet juice. Those days were simple, but they were full of joy. I still remember grandma''s warm smile. I was always so happy in that garden.', '小时候,夏天我常住奶奶家。屋后有个小花园。每天早上我们一起浇花。下午奶奶在大树下给我讲old故事。有时我们摘新鲜水果、榨甜果汁。那些日子简单,却充满快乐。我还记得奶奶温暖的笑。那花园是我童年最幸福的地方。', NULL, 'fable', 'passage', 41, 1, '[{"type": "choice", "q": "What did they do every morning?", "options": ["Told stories.", "Picked fruit.", "Made juice.", "Watered the flowers."], "answer": "D", "explanation": "''Every morning, we watered the flowers together.''"}, {"type": "choice", "q": "What is the passage mainly about?", "options": ["A happy childhood memory at grandma''s garden.", "How to grow flowers.", "A summer trip to the city.", "Grandma''s cooking skills."], "answer": "A", "explanation": "全文回忆奶奶花园的幸福童年。"}]'::jsonb, '[{"word": "juice", "cn": "果汁"}, {"word": "joy", "cn": "快乐,喜悦"}, {"word": "childhood", "cn": "童年"}]'::jsonb),
  ('ea2ec27f-dae7-d917-094a-1396c1eea1ef', 7, 'junior_fltrp', 'wy7B', 'U1', 'The kind bus driver', '独白·陌生人的善意(过去时)', 'Last winter, something small made my whole day happy. One cold morning, I ran to the bus stop, but I forgot my bus card at home. I felt worried because I had no money with me. Then the bus driver smiled and said, ''Don''t worry, you can pay me next time.'' I thanked him again and again. That day, I learnt that a small kind act can warm a cold morning. Now I always try to help others, just like that kind driver.', '去年冬天,一件小事让我一整天都开心。一个寒冷的早晨,我跑到公交站,却把公交卡忘在家。我很担心,因为身上没钱。然后司机笑着说:『别担心,下次再付。』我一再谢他。那天我懂得,一个小小的善举能温暖一个寒冷的早晨。现在我总试着帮助别人,就像那位好司机。', NULL, 'fable', 'passage', 46, 2, '[{"type": "choice", "q": "Why did the writer feel worried?", "options": ["The bus was late.", "He lost his bag.", "He forgot his bus card and had no money.", "It started to rain."], "answer": "C", "explanation": "''I forgot my bus card... I had no money with me.''"}, {"type": "choice", "q": "What did the writer learn?", "options": ["Winter is cold.", "A small kind act can warm a cold morning.", "Buses are often late.", "Money is important."], "answer": "B", "explanation": "末句点题。"}]'::jsonb, '[{"word": "worried", "cn": "担心的"}, {"word": "act", "cn": "行为,举动"}]'::jsonb),
  ('053541c4-a7b9-cd2e-7b77-2c2a6fcc8d20', 7, 'junior_fltrp', 'wy7B', 'U1', 'Happiness Week', '通知·幸福周', 'Hello, students. Here is some news about our Happiness Week. Next week, our school will do many kind things together. On Monday, we will write thank-you cards to our teachers. On Wednesday, we will share our favourite books with the new students. On Friday, we will clean the school garden. Come and join us. Let''s make everyone happy together!', '同学们好,关于幸福周的通知。下周学校将一起做许多善事。周一给老师写感谢卡。周三和低年级同学分享我们最爱的书。周五打扫校园花园。快来参加,让我们一起让大家开心!', NULL, 'fable', 'notice', 33, 1, '[{"type": "choice", "q": "What will students do on Friday?", "options": ["Write cards.", "Share books.", "Sing songs.", "Clean the school garden."], "answer": "D", "explanation": "''On Friday, we will clean the school garden.''"}, {"type": "choice", "q": "What is the Happiness Week about?", "options": ["Doing kind things to make everyone happy.", "A sports match.", "A book sale.", "A maths test."], "answer": "A", "explanation": "通知主体=一起做善事让大家开心。"}]'::jsonb, '[{"word": "thank-you card", "cn": "感谢卡"}]'::jsonb),
  ('7fa9ed83-7307-6313-5cff-3ac7b407b982', 7, 'junior_fltrp', 'wy7B', 'U2', 'Try something new', '鼓励尝试(不定代词)', 'A: I want to join the school race, but I''m not sure. What if I lose?
B: Don''t worry! Everyone feels a little afraid at first.
A: But I''m not a fast runner.
B: That''s OK. You can learn something from every try.
A: You''re right. I''ll give it a go!
B: Great! Anyone can do well with practice.', 'A:我想参加学校赛跑,但没把握,输了怎么办?B:别担心!每个人一开始都有点害怕。A:可我们班没人跑得比我慢。B:没关系,每次尝试你都能学到点东西。A:你说得对,我试试!B:好!谁都能通过练习变得更好。', NULL, 'fable', 'dialogue', 32, 1, '[{"type": "choice", "q": "How does everyone feel at first, according to B?", "options": ["Very happy.", "A little afraid.", "Quite bored.", "Very angry."], "answer": "B", "explanation": "''Everyone feels a little afraid at first.''"}, {"type": "choice", "q": "What does B want A to do?", "options": ["Give up the race.", "Run away.", "Stay at home.", "Try the race and learn from it."], "answer": "D", "explanation": "鼓励尝试、从每次尝试中学习。"}]'::jsonb, '[{"word": "race", "cn": "赛跑,比赛"}]'::jsonb),
  ('b82a85ff-2cc5-3b48-983e-581c060f32d4', 7, 'junior_fltrp', 'wy7B', 'U2', 'Is anyone there?', '找人帮忙(不定代词)', 'A: I dropped my keys somewhere near the gate. Is anyone there to help?
B: I''m here! Let''s look together. Did you check everything in your bag?
A: Yes, there''s nothing in it. Maybe the keys are on the ground.
B: Look, something is shining under the tree!
A: Oh, that''s them! Thank you so much.
B: No problem. Everyone needs a hand sometimes.', 'A:我把钥匙掉在门口附近了,有人能帮忙吗?B:我在!一起找。包里的东西都检查了吗?A:检查了,里面什么都没有,钥匙一定在地上。B:看,树下有东西在发光!A:哦,就是它!太谢谢了。B:不客气,每个人有时都需要帮一把。', NULL, 'fable', 'dialogue', 34, 2, '[{"type": "choice", "q": "Where were the keys?", "options": ["On the ground under the tree.", "In the bag.", "On the gate.", "In the classroom."], "answer": "A", "explanation": "''something is shining under the tree'' → 地上树下。"}, {"type": "choice", "q": "What does B mean at the end?", "options": ["No one likes keys.", "The bag is empty.", "Everyone sometimes needs help.", "The tree is tall."], "answer": "C", "explanation": "''Everyone needs a hand sometimes.''"}]'::jsonb, '[{"word": "keys", "cn": "钥匙"}, {"word": "shining", "cn": "发光的"}]'::jsonb),
  ('723e781e-f0f3-a809-f0da-9adb1c6ceec2', 7, 'junior_fltrp', 'wy7B', 'U2', 'The school got talent show', '才艺秀报名(不定代词)', 'A: There''s a talent show next week. Are you going to do anything?
B: I''d love to, but I can''t do anything special.
A: That''s not true! Everyone has a talent. You draw so well.
B: Do you really think so?
A: Of course. You could show something you painted.
B: OK, I''ll go for it. Nothing is impossible if I try!', 'A:下周有才艺秀,你要表演点什么吗?B:我很想,但我没什么特别的本事。A:才不是!每个人都有才能,你画画那么好。B:你真这么想?A:当然,你可以展示你画的东西。B:好,我拼了!只要尝试,没什么不可能!', NULL, 'fable', 'dialogue', 33, 1, '[{"type": "choice", "q": "What is B good at?", "options": ["Singing.", "Drawing.", "Running.", "Cooking."], "answer": "B", "explanation": "''You draw so well.''"}, {"type": "choice", "q": "What does B decide at the end?", "options": ["To stay at home.", "To sing a song.", "To watch only.", "To take part and show a painting."], "answer": "D", "explanation": "决定参加、展示画作。"}]'::jsonb, '[{"word": "talent", "cn": "才能,天赋"}]'::jsonb),
  ('7c94b6cb-ed97-2d53-e188-4febbb1bdf9b', 7, 'junior_fltrp', 'wy7B', 'U2', 'Never give up', '独白·永不放弃(不定代词)', 'Last year, I joined a long race. At the start, everyone ran fast, and soon I was at the back. My legs hurt, and I wanted to stop. But something inside me said, ''Don''t give up.'' So I kept going, step by step. My best friend cheered for me all the way. At last, I reached the end. I was not first, but I finished. That day taught me a lesson: anyone can win if they never give up.', '去年我参加了一场长跑。起跑时大家都跑得快,我很快落到最后。腿疼,我想停下。但心里有个声音说:『别放弃。』于是我一步步坚持。没有人比我最好的朋友喊得更响。最后我到达终点。我不是最快的,但我跑完了。那天我懂得:只要永不放弃,谁都能赢。', NULL, 'fable', 'passage', 44, 1, '[{"type": "choice", "q": "What did something inside the writer say?", "options": ["Don''t give up.", "Run every day.", "Stop now.", "Go home."], "answer": "A", "explanation": "''something inside me said, Don''t give up.''"}, {"type": "choice", "q": "What did the writer learn?", "options": ["A fast runner always wins.", "Races are boring.", "Anyone can win if they never give up.", "Friends are not important."], "answer": "C", "explanation": "末句点题。"}]'::jsonb, '[{"word": "hurt", "cn": "疼痛"}, {"word": "reached", "cn": "到达(reach的过去式)"}]'::jsonb),
  ('5440dcfb-3709-ea0b-9b00-1987e2808003', 7, 'junior_fltrp', 'wy7B', 'U2', 'Everyone can help', '独白·人人可出力(不定代词)', 'Our class wanted to make the school garden green and nice. At first, someone said, ''It''s too big. We can''t do anything.'' But our teacher smiled. ''Everyone can do something small,'' she said. So we started. Some students planted flowers, and others cleaned the paths. Nobody sat and did nothing. In two weeks, the garden looked wonderful. We learnt that when everyone helps, nothing is too hard.', '我们班想让校园花园更绿。起初有人说:『太大了,我们什么都做不了。』但老师笑了。『每个人都能做点小事,』她说。于是我们开始了。有的同学种花,有的清扫小路。没有人闲坐着什么都不做。两周后,花园变得很美。我们懂得:当人人出力,没有什么太难。', NULL, 'fable', 'passage', 38, 2, '[{"type": "choice", "q": "What did some students do?", "options": ["Cleaned the windows.", "Painted the wall.", "Watered the trees.", "Planted flowers and cleaned the paths."], "answer": "D", "explanation": "''Some students planted flowers, and others cleaned the paths.''"}, {"type": "choice", "q": "What is the main idea?", "options": ["Gardens are hard to make.", "Teachers do all the work.", "When everyone helps, nothing is too hard.", "Flowers grow fast."], "answer": "C", "explanation": "末句点题。"}]'::jsonb, '[{"word": "paths", "cn": "小路"}]'::jsonb),
  ('f33944c3-1451-6161-b338-b93d91cdfef1', 7, 'junior_fltrp', 'wy7B', 'U2', 'The sports challenge', '通知·运动挑战(不定代词)', 'Hello, students. Here is some news about our Sports Challenge. Next Friday, everyone can take part in our fun games. There is something for everybody: running, jumping and ball games. You don''t need to be very good at anything. Just come and try your best. Anyone who joins will get a small gift. Let''s go for it together!', '同学们好,关于运动挑战的通知。下周五,人人都能参加我们的趣味运动。每个人都有适合的项目:跑步、跳跃、球类游戏。你不需要在任何项目上最厉害。来尽力就好。参加的每个人都会得到一份小礼物。一起加油吧!', NULL, 'fable', 'notice', 33, 1, '[{"type": "choice", "q": "What will anyone who joins get?", "options": ["A medal.", "A small gift.", "A book.", "A photo."], "answer": "B", "explanation": "''Anyone who joins will get a small gift.''"}, {"type": "choice", "q": "What is the notice mainly about?", "options": ["A sports challenge everyone can join.", "A maths test.", "A book club.", "A music show."], "answer": "A", "explanation": "通知主体=人人可参加的运动挑战。"}]'::jsonb, '[{"word": "take part", "cn": "参加"}]'::jsonb),
  ('9955b797-efd1-c710-f105-a7a33ae84e84', 7, 'junior_fltrp', 'wy7B', 'U3', 'This soup tastes great', '尝味道(系动词)', 'A: Mum, this soup smells so good! What''s in it?
B: Fresh vegetables and a little chicken. Try some.
A: Mmm, it tastes great! It''s warm and sweet.
B: Wonderful! Healthy food can taste nice too.
A: You''re right. This looks really fresh and good.
B: And it makes you feel strong and healthy.', 'A:妈妈,这汤闻起来真香!里面有什么?B:新鲜蔬菜和一点鸡肉,尝尝。A:嗯,味道真好!又暖又甜。B:你喜欢我就高兴。健康的食物也能好吃。A:对,这比快餐看起来好多了。B:而且它让你感觉强壮又健康。', NULL, 'fable', 'dialogue', 28, 1, '[{"type": "choice", "q": "How does the soup taste?", "options": ["Sour.", "Too salty.", "Cold.", "Great, warm and sweet."], "answer": "D", "explanation": "''it tastes great! It''s warm and sweet.''"}, {"type": "choice", "q": "What does the dialogue mainly tell us?", "options": ["Healthy food can taste nice and make you strong.", "Fast food is the best.", "Soup is hard to cook.", "Chicken is cheap."], "answer": "A", "explanation": "健康食物也好吃、让人强壮。"}]'::jsonb, '[{"word": "soup", "cn": "汤"}, {"word": "vegetables", "cn": "蔬菜"}, {"word": "chicken", "cn": "鸡肉"}]'::jsonb),
  ('a68b08af-63da-bab2-f643-e1df53570954', 7, 'junior_fltrp', 'wy7B', 'U3', 'The bread went bad', '食物变质(系动词get/become)', 'A: Can I eat this bread? It looks a bit strange.
B: Let me see. Oh, it smells bad. The bread went bad.
A: Really? It felt soft yesterday.
B: Bread gets old quickly in summer. Let''s not eat it.
A: OK. What else do we have?
B: There are some fresh apples. They look sweet and juicy.', 'A:这面包能吃吗?看着有点怪。B:我看看。哦,闻着坏了,我觉得它变质了。A:真的?昨天还软软的。B:夏天面包坏得快,别吃了。A:好,我们还有什么?B:有些新鲜苹果,看起来又甜又多汁。', NULL, 'fable', 'dialogue', 29, 2, '[{"type": "choice", "q": "Why won''t they eat the bread?", "options": ["It is too hard.", "It looks green.", "It smells bad and it went bad.", "It is too sweet."], "answer": "C", "explanation": "''it smells bad. I think it went bad.''"}, {"type": "choice", "q": "What will they probably eat instead?", "options": ["More bread.", "Fresh apples.", "Some soup.", "Nothing."], "answer": "B", "explanation": "''There are some fresh apples.''"}]'::jsonb, '[{"word": "bread", "cn": "面包"}, {"word": "juicy", "cn": "多汁的"}]'::jsonb),
  ('f2b152c6-4201-4753-3c97-ccca02e623d2', 7, 'junior_fltrp', 'wy7B', 'U3', 'Cooking with Dad', '和爸爸做饭(系动词)', 'A: Dad, the rice is ready. Does it look right?
B: It looks perfect. Now let''s taste the fish.
A: It tastes a little salty to me.
B: You''re right. Let''s add some water. How about now?
A: Very good! It tastes fresh now.
B: Cooking together makes dinner more fun, doesn''t it?', 'A:爸爸,米饭好了,看着对吗?B:看着正好。来尝尝鱼。A:我觉得有点咸。B:你说得对,加点水。现在呢?A:好多了!现在味道很鲜。B:一起做饭让晚餐更有趣,对吧?', NULL, 'fable', 'dialogue', 28, 1, '[{"type": "choice", "q": "What was wrong with the fish at first?", "options": ["It tasted a little salty.", "It looked bad.", "It smelled strange.", "It was cold."], "answer": "A", "explanation": "''It tastes a little salty to me.''"}, {"type": "choice", "q": "What does Dad think about cooking together?", "options": ["It is too hard.", "It makes dinner more fun.", "It takes too long.", "It is boring."], "answer": "B", "explanation": "''Cooking together makes dinner more fun.''"}]'::jsonb, '[{"word": "salty", "cn": "咸的"}, {"word": "fish", "cn": "鱼"}]'::jsonb),
  ('fe8a7478-6e1a-f4ee-276b-f06f547af22b', 7, 'junior_fltrp', 'wy7B', 'U3', 'My favourite food', '独白·最爱的食物(系动词)', 'My favourite food is dumplings. On cold days, they look warm and lovely on the plate. When they are ready, they smell wonderful, and the whole kitchen feels warm. Each dumpling tastes soft outside and full inside. My grandma has a saying: good food should make people feel happy. And she is right. Every time I eat her dumplings, I feel warm and safe, just like home.', '我最爱的食物是饺子。冷天里,它们在盘子上看着又暖又可爱。做好时,香气扑鼻,整个厨房都暖暖的。每个饺子外软内满。奶奶说好食物应该让人开心。我觉得她说得对。每次吃她的饺子,我都感到温暖又安心,就像家一样。', NULL, 'fable', 'passage', 37, 1, '[{"type": "choice", "q": "How do the dumplings smell when ready?", "options": ["Strange.", "Sour.", "Wonderful.", "Bad."], "answer": "C", "explanation": "''they smell wonderful.''"}, {"type": "choice", "q": "What does grandma think good food should do?", "options": ["Look expensive.", "Be very sweet.", "Take a long time.", "Make people feel happy."], "answer": "D", "explanation": "''good food should make people feel happy.''"}]'::jsonb, '[{"word": "kitchen", "cn": "厨房"}, {"word": "plate", "cn": "盘子"}]'::jsonb),
  ('b500a4d8-b1c6-e7c8-18dc-fdf2bd38beb9', 7, 'junior_fltrp', 'wy7B', 'U3', 'Healthy eating', '独白·健康饮食(系动词)', 'Many students think healthy food tastes boring, but that is not true. Fresh fruit tastes sweet, and warm soup smells great on a cold day. When we eat well, we feel strong and our minds stay clear. Too much fast food makes us feel tired and slow. My teacher says, ''You are what you eat.'' So I try to eat more vegetables and fruit. Now I feel healthy and happy every day.', '很多学生以为健康食物没味道,其实不是。新鲜水果是甜的,冷天里热汤香气扑鼻。吃得好,我们感觉强壮,头脑清醒。吃太多快餐让我们又累又迟钝。老师说:『人如其食。』所以我尽量多吃蔬菜水果。现在我一天天更健康、更开心。', NULL, 'fable', 'passage', 39, 2, '[{"type": "choice", "q": "How does too much fast food make us feel?", "options": ["Strong.", "Happy.", "Tired and slow.", "Clear."], "answer": "C", "explanation": "''Too much fast food makes us feel tired and slow.''"}, {"type": "choice", "q": "What is the main idea?", "options": ["Healthy food tastes nice and keeps us strong.", "Fast food is delicious.", "Soup is only for winter.", "Fruit is too sweet."], "answer": "A", "explanation": "全文讲健康饮食好吃又强身。"}]'::jsonb, '[{"word": "minds", "cn": "头脑,思维"}, {"word": "clear", "cn": "清醒的"}]'::jsonb),
  ('12c20767-1439-3113-8d46-b3279d1d7703', 7, 'junior_fltrp', 'wy7B', 'U3', 'Healthy Food Week', '通知·健康饮食周(系动词)', 'Good morning, students. Here is some news about our Healthy Food Week. Next week, the school will teach us about good eating. On Monday, we will taste fresh fruit from different places. On Wednesday, a cook will show us how to make a simple healthy meal. On Friday, everyone can bring a healthy dish to share. Good food makes us feel great. Come and join us!', '同学们早上好,关于健康饮食周的通知。下周学校将教我们健康饮食。周一品尝来自各地的新鲜水果。周三一位厨师教我们做简单健康餐。周五人人可带一道健康菜来分享。好食物让我们感觉很棒。快来参加!', NULL, 'fable', 'notice', 36, 1, '[{"type": "choice", "q": "What will students do on Friday?", "options": ["Taste fruit.", "Bring a healthy dish to share.", "Watch a cook.", "Clean the kitchen."], "answer": "B", "explanation": "''On Friday, everyone can bring a healthy dish to share.''"}, {"type": "choice", "q": "What is the notice mainly about?", "options": ["A cooking match.", "A fruit sale.", "A sports day.", "A week about healthy eating."], "answer": "D", "explanation": "通知主体=健康饮食周。"}]'::jsonb, '[{"word": "dish", "cn": "一道菜"}, {"word": "meal", "cn": "一餐"}]'::jsonb),
  ('ac8848ea-f275-8dca-5b54-6f5390b4f07c', 7, 'junior_fltrp', 'wy7B', 'U4', 'Let''s play a game', '教玩游戏(祈使句)', 'A: I''m bored. Let''s play a game!
B: Good idea! Come here and I''ll teach you one.
A: OK, what do I do?
B: First, close your eyes. Then listen to the sounds around you.
A: That''s fun! I can hear birds and the wind.
B: Right! Don''t open your eyes yet. Just enjoy the quiet.', 'A:我好无聊,我们玩个游戏吧!B:好主意!到这来,我教你一个。A:好,我要做什么?B:先闭上眼睛,然后听周围的声音。A:真有趣!我能听到鸟和风。B:对!先别睁眼,好好享受这份安静。', NULL, 'fable', 'dialogue', 30, 1, '[{"type": "choice", "q": "What should A do first?", "options": ["Open the window.", "Close the eyes.", "Run around.", "Sing a song."], "answer": "B", "explanation": "''First, close your eyes.''"}, {"type": "choice", "q": "What kind of game is it?", "options": ["A running game.", "A ball game.", "A quiet game about listening to sounds.", "A word game."], "answer": "C", "explanation": "闭眼听声音的安静游戏。"}]'::jsonb, '[{"word": "bored", "cn": "无聊的"}]'::jsonb),
  ('0dfa3bf6-c8a7-9e4b-3aea-314d742c561a', 7, 'junior_fltrp', 'wy7B', 'U4', 'Make a paper boat', '教折纸船(祈使句)', 'A: Can you show me how to make a paper boat?
B: Sure! Take this square paper first.
A: OK, I have it now.
B: Now fold it in the middle. Be careful, don''t tear it.
A: Like this?
B: Perfect! Fold the corners, and there''s your boat. Well done!', 'A:你能教我折纸船吗?B:当然!先拿这张方形纸。A:好,拿到了。B:现在从中间对折。小心,别撕破了。A:像这样?B:完美!把角折一下,你的船就好了。做得好!', NULL, 'fable', 'dialogue', 25, 2, '[{"type": "choice", "q": "What should A be careful not to do?", "options": ["Tear the paper.", "Fold the paper.", "Take the paper.", "Colour the paper."], "answer": "A", "explanation": "''Be careful, don''t tear it.''"}, {"type": "choice", "q": "What are they making?", "options": ["A paper plane.", "A paper hat.", "A paper flower.", "A paper boat."], "answer": "D", "explanation": "''make a paper boat.''"}]'::jsonb, '[{"word": "fold", "cn": "折叠"}, {"word": "square", "cn": "正方形的"}]'::jsonb),
  ('32492f4f-e561-2eb9-d14d-db40cf6a7b1d', 7, 'junior_fltrp', 'wy7B', 'U4', 'Come to the park', '邀约玩耍(祈使句)', 'A: It''s a sunny day. Don''t stay inside, Ben!
B: You''re right. What shall we do?
A: Come to the park with me. Bring your kite!
B: Great idea. Let''s ask Lily to join us too.
A: Sure. Call her now, and let''s go together.
B: OK! Wait for me at the gate.', 'A:今天天气真好,别待在屋里,Ben!B:你说得对,我们做什么?A:跟我去公园,带上你的风筝!B:好主意,我们也叫上Lily吧。A:好,现在给她打电话,一起去。B:好!在大门口等我。', NULL, 'fable', 'dialogue', 28, 1, '[{"type": "choice", "q": "What does A ask Ben to bring?", "options": ["A ball.", "Some food.", "His kite.", "A book."], "answer": "C", "explanation": "''Bring your kite!''"}, {"type": "choice", "q": "What are they going to do?", "options": ["Go to the park and fly a kite together.", "Stay at home.", "Do homework.", "Watch TV."], "answer": "A", "explanation": "去公园放风筝。"}]'::jsonb, '[{"word": "kite", "cn": "风筝"}]'::jsonb),
  ('d7398f1e-0d27-2e36-cbd4-f0aae2bae51a', 7, 'junior_fltrp', 'wy7B', 'U4', 'How to have fun at home', '独白·居家玩乐(祈使句)', 'Do you feel bored at home on a rainy day? Don''t worry! There are many ways to have fun. First, find some old boxes and make a small house. Then invite your family to play inside. You can also draw pictures or read a funny story together. Remember, don''t just look at a screen all day. Use your hands and your mind. Try these ideas, and you will see — home can be a fun place too.', '下雨天在家觉得无聊吗?别担心!有很多找乐子的方法。首先,找些旧箱子搭个小房子,然后邀请家人进去玩。你也可以一起画画或读个有趣的故事。记住,别整天只盯着屏幕。动动手、动动脑。试试这些主意,你会发现家里也能很好玩。', NULL, 'fable', 'passage', 43, 1, '[{"type": "choice", "q": "What does the writer tell us to make with old boxes?", "options": ["A boat.", "A small house.", "A kite.", "A car."], "answer": "B", "explanation": "''make a small house.''"}, {"type": "choice", "q": "What is the passage mainly about?", "options": ["How to draw pictures.", "Why screens are bad.", "How to read stories.", "Ways to have fun at home on a rainy day."], "answer": "D", "explanation": "全文讲雨天居家找乐子的方法。"}]'::jsonb, '[{"word": "boxes", "cn": "箱子"}, {"word": "screen", "cn": "屏幕"}]'::jsonb),
  ('ba1e596b-6757-77e1-6d33-fde199b0de0c', 7, 'junior_fltrp', 'wy7B', 'U4', 'Our fun club', '独白·社团玩乐(祈使句)', 'Welcome to our fun club! Here are some simple rules. Come every Friday afternoon and bring a smile. Don''t be shy — everyone is a friend here. First, choose a game you like. Then find some friends and play together. If someone makes a mistake, don''t laugh at them. Help them and try again. Remember, having fun is not about winning. Just enjoy your time. Come and join us this week!', '欢迎来到我们的趣味社团!这里有些简单规则。每周五下午来,带上笑容。别害羞——这里人人都是朋友。首先,选一个你喜欢的游戏,然后找些朋友一起玩。如果有人出错,别嘲笑他们,帮他们再试一次。记住,玩乐不在输赢,只管享受时光。这周就来加入我们吧!', NULL, 'fable', 'passage', 39, 2, '[{"type": "choice", "q": "What should you do if someone makes a mistake?", "options": ["Laugh at them.", "Help them and try again.", "Leave them.", "Stop the game."], "answer": "B", "explanation": "''Help them and try again.''"}, {"type": "choice", "q": "What is the club''s main idea about fun?", "options": ["Winning is all that matters.", "Only good players can join.", "Games must be quiet.", "Fun is not about winning, just enjoy your time."], "answer": "D", "explanation": "''having fun is not about winning.''"}]'::jsonb, '[{"word": "shy", "cn": "害羞的"}, {"word": "mistake", "cn": "错误"}]'::jsonb),
  ('2e8f11de-c805-ec23-8595-29f14d666888', 7, 'junior_fltrp', 'wy7B', 'U4', 'Game Day', '通知·游戏日(祈使句)', 'Hello, students. Here is some news about our Game Day. Come to the playground next Wednesday afternoon. Please bring your favourite games and a lot of energy. Don''t forget to wear your sports shoes. First, find a group of friends. Then choose a game and play together. Remember, be kind and share with everyone. Let''s have a wonderful day of fun. See you there!', '同学们好,关于游戏日的通知。下周三下午来操场。带上你最爱的游戏和满满的活力。别忘了穿运动鞋。先找一群朋友,然后选个游戏一起玩。记住,友善待人、和大家分享。让我们度过美好玩乐的一天。到时见!', NULL, 'fable', 'notice', 36, 1, '[{"type": "choice", "q": "What should students not forget to wear?", "options": ["Their sports shoes.", "A hat.", "A coat.", "Gloves."], "answer": "A", "explanation": "''Don''t forget to wear your sports shoes.''"}, {"type": "choice", "q": "What is the notice mainly about?", "options": ["A maths lesson.", "A quiet reading day.", "A Game Day for students to play together.", "A school trip."], "answer": "C", "explanation": "通知主体=游戏日。"}]'::jsonb, '[{"word": "energy", "cn": "活力,精力"}]'::jsonb),
  ('4bff0a88-3be5-03da-10e6-32830b544580', 7, 'junior_fltrp', 'wy7B', 'U5', 'The tallest mountain', '比较自然(比较级最高级)', 'A: Look at this photo! Is that the tallest mountain in the world?
B: Yes, it is. It''s much taller than any mountain near our town.
A: Wow, it looks amazing. Is it colder up there?
B: Of course. The higher you go, the colder it gets.
A: I''d love to see it one day.
B: Me too. Nature is more wonderful than any picture.', 'A:看这张照片!那是世界最高的山吗?B:是的,它比我们镇附近任何山都高得多。A:哇,真壮观。上面更冷吗?B:当然,爬得越高越冷。A:真想有一天亲眼看看。B:我也是。大自然比任何图片都更奇妙。', NULL, 'fable', 'dialogue', 33, 1, '[{"type": "choice", "q": "How is the weather higher up the mountain?", "options": ["Warmer.", "Wetter.", "Sunnier.", "Colder."], "answer": "D", "explanation": "''The higher you go, the colder it gets.''"}, {"type": "choice", "q": "What does B think about nature?", "options": ["It is boring.", "It is dangerous.", "It is more wonderful than any picture.", "It is small."], "answer": "C", "explanation": "''Nature is more wonderful than any picture.''"}]'::jsonb, '[{"word": "mountain", "cn": "山"}]'::jsonb),
  ('d19578f3-a211-755d-c1d2-8dd322f3037e', 7, 'junior_fltrp', 'wy7B', 'U5', 'Which animal is bigger?', '比较动物(比较级)', 'A: The elephant is the biggest animal on land, right?
B: You''re right. But the blue whale in the sea is even bigger.
A: Really? Bigger than an elephant?
B: Yes, much bigger! It''s the largest animal in the world.
A: That''s amazing. The sea is really full of wonders.
B: It is. Some sea animals are stranger than any land animal.', 'A:我觉得大象是陆地上最大的动物。B:对,但海里的蓝鲸更大。A:真的?比大象还大?B:是的,大得多!它是世界上最大的动物。A:太神奇了,海里一定满是奇观。B:是的,有些海洋动物比任何陆地动物都更奇特。', NULL, 'fable', 'dialogue', 32, 2, '[{"type": "choice", "q": "What is the largest animal in the world?", "options": ["The blue whale.", "The elephant.", "The shark.", "The bird."], "answer": "A", "explanation": "''It''s the largest animal in the world.''(blue whale)"}, {"type": "choice", "q": "What does the dialogue tell us about the sea?", "options": ["It is empty.", "It is full of amazing animals.", "It is very small.", "It has no animals."], "answer": "B", "explanation": "''The sea is really full of wonders.''"}]'::jsonb, '[{"word": "elephant", "cn": "大象"}, {"word": "whale", "cn": "鲸"}]'::jsonb),
  ('50eb3121-4f32-e897-cc69-eb03fce1c859', 7, 'junior_fltrp', 'wy7B', 'U5', 'Spring is the best', '比较季节(最高级)', 'A: Which season do you like best, Lily?
B: I like spring the most. It''s the most beautiful season.
A: Why do you think so?
B: The flowers are brighter, and the days are warmer than in winter.
A: That''s true. Summer is hotter, but spring feels just right.
B: Exactly. Nothing is nicer than a warm spring day.', 'A:Lily你最喜欢哪个季节?B:我最喜欢春天,它是最美的季节。A:为什么这么想?B:花更艳,白天比冬天暖和。A:确实,夏天更热,但春天刚刚好。B:没错,没有什么比一个温暖的春日更美好。', NULL, 'fable', 'dialogue', 30, 1, '[{"type": "choice", "q": "Why does Lily like spring most?", "options": ["It is the coldest.", "It is the shortest.", "It rains a lot.", "The flowers are brighter and the days are warmer."], "answer": "D", "explanation": "''The flowers are brighter, and the days are warmer.''"}, {"type": "choice", "q": "What is Lily''s opinion?", "options": ["Spring is the most beautiful season.", "Winter is the best.", "Summer is too cold.", "Autumn is boring."], "answer": "A", "explanation": "''It''s the most beautiful season.''"}]'::jsonb, '[{"word": "season", "cn": "季节"}, {"word": "bright", "cn": "鲜艳的,明亮的"}]'::jsonb),
  ('7f0d9d27-0266-585d-a115-c9241282db4d', 7, 'junior_fltrp', 'wy7B', 'U5', 'The amazing sea', '独白·神奇海洋(比较级)', 'The sea is one of the most amazing places on the earth. It is much bigger than all the land put together. Some parts of the sea are deeper than the tallest mountain is high. In the sea live the largest animals in the world, and also some of the smallest. The water looks bluer near the beach and darker far away. The more we learn about the sea, the more wonderful it becomes. We should protect this amazing world of water.', '大海是地球上最神奇的地方之一。它比所有陆地加起来还大得多。海的有些地方比最高的山还深。海里生活着世界上最大的动物,也有一些最小的。靠近沙滩海水更蓝,远处更暗。我们对大海了解越多,它就越奇妙。我们应该保护这个神奇的水世界。', NULL, 'fable', 'passage', 45, 1, '[{"type": "choice", "q": "How does the water look near the beach?", "options": ["Darker.", "Bluer.", "Greener.", "Redder."], "answer": "B", "explanation": "''The water looks bluer near the beach.''"}, {"type": "choice", "q": "What is the passage mainly about?", "options": ["How to swim in the sea.", "Why mountains are tall.", "How amazing the sea is and why we should protect it.", "How fish sleep."], "answer": "C", "explanation": "全文讲大海的神奇与保护。"}]'::jsonb, '[{"word": "deep", "cn": "深的"}, {"word": "beach", "cn": "沙滩,海滩"}]'::jsonb),
  ('44acf621-71ee-7adb-8367-1604eea88138', 7, 'junior_fltrp', 'wy7B', 'U5', 'Trees are our best friends', '独白·树的价值(比较级)', 'Trees are some of the most important living things on the earth. A big old tree is stronger than it looks. It gives us cooler air in summer and cleaner air all year. Under a tree, the ground is wetter, so more plants can grow. Birds build safer homes in the highest branches. The more trees we plant, the greener our world becomes. So let''s plant more trees. Nothing gives more and asks for less than a tree.', '树是地球上最重要的生命之一。一棵高大的老树比看上去更强壮。它给我们夏天更凉的空气、全年更洁净的空气。树下地面更湿,所以更多植物能生长。鸟在最高的树枝上筑更安全的巢。我们种的树越多,世界就越绿。所以让我们多种树。没有什么比一棵树给予更多、索取更少。', NULL, 'fable', 'passage', 43, 2, '[{"type": "choice", "q": "Why can more plants grow under a tree?", "options": ["The air is warmer.", "The ground is wetter.", "The ground is drier.", "There is more light."], "answer": "B", "explanation": "''the ground is wetter, so more plants can grow.''"}, {"type": "choice", "q": "What does the writer ask us to do?", "options": ["Cut down trees.", "Move the trees.", "Water the sea.", "Plant more trees."], "answer": "D", "explanation": "''let''s plant more trees.''"}]'::jsonb, '[{"word": "branches", "cn": "树枝"}]'::jsonb),
  ('cb178222-8e7c-4866-0bcf-7c6f4df4f8ed', 7, 'junior_fltrp', 'wy7B', 'U5', 'Nature Photo Show', '通知·自然摄影展(比较级)', 'Good morning, students. Here is some news about our Nature Photo Show. Next week, we will show the most beautiful nature photos taken by students. Some show the tallest trees, and others show the smallest insects. Come and find the photo you like best. The best three photos will get a prize. Bring your friends and enjoy the amazing world of nature. See you in the school hall!', '同学们早上好,关于自然摄影展的通知。下周我们将展出学生拍的最美的自然照片。有的展示最高的树,有的展示最小的昆虫。来找出你最喜欢的照片。最好的三张会得奖。带上朋友,享受神奇的自然世界。学校礼堂见!', NULL, 'fable', 'notice', 37, 1, '[{"type": "choice", "q": "How many photos will get a prize?", "options": ["One.", "Two.", "Three.", "Four."], "answer": "C", "explanation": "''The best three photos will get a prize.''"}, {"type": "choice", "q": "What is the notice mainly about?", "options": ["A nature photo show at school.", "A sports day.", "A tree planting day.", "A food festival."], "answer": "A", "explanation": "通知主体=自然摄影展。"}]'::jsonb, '[{"word": "insects", "cn": "昆虫"}, {"word": "prize", "cn": "奖品"}]'::jsonb),
  ('38cb0e1f-d27d-0e8c-fe84-8ba73ccfa978', 7, 'junior_fltrp', 'wy7B', 'U6', 'Planning our trip', '计划出行(as...as)', 'A: Let''s plan our trip. Should we go by train or by bus?
B: The train is not as cheap as the bus, but it''s much faster.
A: True. And the train is as comfortable as our sofa at home!
B: Ha, almost! Let''s take the early train, so we have more time there.
A: Good idea. Remember to pack as light as you can.
B: Sure. A small bag is easier to carry.', 'A:我们来计划旅行。坐火车还是公交?B:火车没公交便宜,但快得多。A:对,而且火车跟家里沙发一样舒服!B:哈,差不多!我们坐早班火车,那样在那边时间更多。A:好主意。记得尽量轻装。B:好,小包更好拿。', NULL, 'fable', 'dialogue', 39, 1, '[{"type": "choice", "q": "Why do they choose the train?", "options": ["It is the cheapest.", "It is much faster than the bus.", "It is the slowest.", "It has no seats."], "answer": "B", "explanation": "''the train... is much faster.''"}, {"type": "choice", "q": "What does B tell A to remember?", "options": ["To bring a big bag.", "To take the late train.", "To stay at home.", "To pack as light as possible."], "answer": "D", "explanation": "''pack as light as you can.''"}]'::jsonb, '[{"word": "comfortable", "cn": "舒适的"}, {"word": "pack", "cn": "打包,装(行李)"}]'::jsonb),
  ('d26607f0-0055-9284-c0d9-d290b09993ba', 7, 'junior_fltrp', 'wy7B', 'U6', 'A day at the beach', '海边一天(as...as·过去时)', 'A: How was your trip to the beach yesterday?
B: Wonderful! The sea was as blue as the sky.
A: That sounds beautiful. Was it crowded?
B: Not as crowded as last summer. We had lots of space.
A: Lucky you! Did you swim?
B: Yes, and the water was not as cold as I thought. It was a perfect day.', 'A:昨天去海边玩得怎么样?B:太棒了!大海跟天空一样蓝。A:听着真美,人多吗?B:没有去年夏天那么多,我们有很多空间。A:真幸运!游泳了吗?B:游了,水没我想的那么冷。真是完美的一天。', NULL, 'fable', 'dialogue', 30, 2, '[{"type": "choice", "q": "How was the sea?", "options": ["As grey as stone.", "As dark as night.", "As blue as the sky.", "As cold as ice."], "answer": "C", "explanation": "''The sea was as blue as the sky.''"}, {"type": "choice", "q": "Why was the day perfect for B?", "options": ["It was not crowded and the water was not too cold.", "It rained all day.", "The beach was closed.", "The sea was too rough."], "answer": "A", "explanation": "人不多、水不太冷 → 完美。"}]'::jsonb, '[{"word": "crowded", "cn": "拥挤的"}, {"word": "space", "cn": "空间"}]'::jsonb),
  ('29de8b4d-8714-5998-8a62-be401e819656', 7, 'junior_fltrp', 'wy7B', 'U6', 'Two bikes', '比较两辆车(as...as)', 'A: I want to buy a new bike. Which one is better?
B: This red one is not as expensive as the blue one.
A: But is it as good?
B: Yes, it''s just as strong and as fast as the blue one.
A: Then I''ll take the red one. It''s as nice as the blue one but cheaper.
B: A smart choice!', 'A:我想买辆新自行车,哪辆更好?B:这辆红的没蓝的那么贵。A:但它一样好吗?B:是的,它跟蓝的一样结实、一样快。A:那我买红的。它跟蓝的一样好看但更便宜。B:明智的选择!', NULL, 'fable', 'dialogue', 33, 1, '[{"type": "choice", "q": "How is the red bike compared with the blue one?", "options": ["More expensive.", "Much slower.", "Just as strong and fast, but cheaper.", "Much weaker."], "answer": "C", "explanation": "''as strong and as fast... but cheaper.''"}, {"type": "choice", "q": "Which bike does A choose and why?", "options": ["The blue one, because it is faster.", "Neither.", "The most expensive one.", "The red one, because it is as good but cheaper."], "answer": "D", "explanation": "选红的:一样好但更便宜。"}]'::jsonb, '[{"word": "expensive", "cn": "昂贵的"}, {"word": "choice", "cn": "选择"}]'::jsonb),
  ('1e091575-27f1-452f-2829-4cede88aff0c', 7, 'junior_fltrp', 'wy7B', 'U6', 'My first train trip', '独白·第一次坐火车(as...as·过去时)', 'Last summer, I took my first long train trip with my family. At first, I expected a train to be as boring as a bus, but I was wrong. The seats were as soft as my bed at home. Outside the window, the fields were as green as a big carpet. We ate, talked and laughed. The hours passed as quickly as minutes. When we arrived, I felt happy and excited. That trip was not as tiring as I feared. I can''t wait for my next journey.', '去年夏天,我和家人第一次坐长途火车。起初我以为火车跟公交一样无聊,但我错了。座位跟我家床一样软。窗外,田野绿得像一大块地毯。我们吃着、聊着、笑着。几个小时过得跟几分钟一样快。到站时,我又开心又激动。那趟旅行没我担心的那么累。希望下次旅程快点来。', NULL, 'fable', 'passage', 48, 1, '[{"type": "choice", "q": "How were the seats on the train?", "options": ["As soft as the writer''s bed.", "As hard as stone.", "As cold as ice.", "As small as a box."], "answer": "A", "explanation": "''The seats were as soft as my bed at home.''"}, {"type": "choice", "q": "How did the writer feel about the train trip?", "options": ["It was very boring.", "It was much better than expected.", "It was too tiring.", "It was too short."], "answer": "B", "explanation": "以为无聊/累,结果很好 → 超出预期。"}]'::jsonb, '[{"word": "fields", "cn": "田野"}, {"word": "carpet", "cn": "地毯"}, {"word": "journey", "cn": "旅程"}]'::jsonb),
  ('6e16aab4-4562-2f84-831d-817a73e59178', 7, 'junior_fltrp', 'wy7B', 'U6', 'Travel light', '独白·轻装出行建议(as...as)', 'When you go on a trip, try to travel as light as you can. A heavy bag is not as fun as a light one, because you have to carry it all day. Take only what you really need. Good shoes are as important as good clothes, so choose them well. Keep your map and water as close as possible. And remember, a happy heart is as useful as any map. If you are ready and relaxed, every journey can be as wonderful as a dream.', '出行时,尽量轻装。重包不如轻包好玩,因为你得背一整天。只带真正需要的。好鞋跟好衣服一样重要,所以要选好。把地图和水放得尽量近。记住,一颗快乐的心跟任何地图一样有用。只要你准备好、放松,每段旅程都能像梦一样美好。', NULL, 'fable', 'passage', 47, 2, '[{"type": "choice", "q": "Why is a heavy bag not as fun as a light one?", "options": ["You have to carry it all day.", "It is more beautiful.", "It is cheaper.", "It holds less."], "answer": "A", "explanation": "''you have to carry it all day.''"}, {"type": "choice", "q": "What is the writer''s main advice?", "options": ["Bring as much as you can.", "Never use a map.", "Travel light and stay relaxed.", "Buy expensive shoes."], "answer": "C", "explanation": "全文建议轻装、放松。"}]'::jsonb, '[{"word": "heavy", "cn": "重的"}, {"word": "relaxed", "cn": "放松的"}]'::jsonb),
  ('41efee43-09c2-bed6-b458-272225c6b515', 7, 'junior_fltrp', 'wy7B', 'U6', 'School Spring Trip', '通知·春游(as...as)', 'Hello, students. Here is some news about our School Spring Trip. Next Friday, we will visit the Green Hill Park. Please come as early as seven thirty and wait at the school gate. Wear shoes as comfortable as you can, because we will walk a lot. Bring some water and a small lunch. The park is as beautiful as a painting in spring. Let''s enjoy a wonderful day in nature together!', '同学们好,关于学校春游的通知。下周五我们将去青山公园。请尽量早点、七点半就来,在校门口等。穿尽量舒适的鞋,因为我们要走很多路。带些水和简单的午餐。春天的公园美得像一幅画。让我们一起在自然中享受美好的一天!', NULL, 'fable', 'notice', 39, 1, '[{"type": "choice", "q": "What time should students come?", "options": ["At seven.", "As early as seven thirty.", "At eight.", "At nine."], "answer": "B", "explanation": "''come as early as seven thirty.''"}, {"type": "choice", "q": "What is the notice mainly about?", "options": ["A sports day.", "A photo show.", "A food week.", "A school spring trip to a park."], "answer": "D", "explanation": "通知主体=学校春游。"}]'::jsonb, '[{"word": "comfortable", "cn": "舒适的"}]'::jsonb);

-- 断言
DO $$
DECLARE tot int; badq int; poll int; peru int;
BEGIN
  SELECT count(*) INTO tot FROM public.junior_listening_exercises WHERE publisher='junior_fltrp' AND volume='wy7B';
  IF tot<>36 THEN RAISE EXCEPTION 'total=% 期望36', tot; END IF;
  SELECT count(*) INTO badq FROM public.junior_listening_exercises WHERE publisher='junior_fltrp' AND volume='wy7B' AND jsonb_array_length(questions)<>2;
  IF badq<>0 THEN RAISE EXCEPTION '题数≠2的篇=%', badq; END IF;
  SELECT count(*) INTO poll FROM public.junior_listening_exercises WHERE volume='wy7B' AND publisher<>'junior_fltrp';
  IF poll<>0 THEN RAISE EXCEPTION 'pep_polluted=%', poll; END IF;
  SELECT count(*) INTO peru FROM (SELECT unit FROM public.junior_listening_exercises WHERE publisher='junior_fltrp' AND volume='wy7B' GROUP BY unit HAVING count(*)<>6) t;
  IF peru<>0 THEN RAISE EXCEPTION '每单元≠6篇的单元数=%', peru; END IF;
  RAISE NOTICE 'OK: wy7B 听力 % 篇 · 6单元各6 · 每篇2题', tot;
END $$;

COMMIT;
SELECT unit, count(*) 篇, sum((audio_url IS NULL)::int) 待生成音频 FROM public.junior_listening_exercises WHERE publisher='junior_fltrp' AND volume='wy7B' GROUP BY unit ORDER BY unit;